<?php

namespace Bga\Games\RegroupChickenArmy\States;

use Bga\Games\RegroupChickenArmy\Components\Market;
use Bga\Games\RegroupChickenArmy\Components\Players;
use Bga\Games\RegroupChickenArmy\Components\Resources;
use Bga\Games\RegroupChickenArmy\Game;
use BgaSystemException;
// BgaUserException not used in this file
use BgaVisibleSystemException;

class RoundSetupStateHandler implements StateHandlerInterface
{
    /* AUTOGENERATED_HANDLE_START - DO NOT REMOVE THIS COMMENT */
    public static function handle(Game $game, string $action, ...$args): void
    {
        switch ($action) {

            default:
                throw new BgaVisibleSystemException("Invalid action: $action");
        }
    }
    /* AUTOGENERATED_HANDLE_END - DO NOT REMOVE THIS COMMENT */


    /**
     * Main method to execute the RoundSetup game state
     */
    public static function executeGameState(Game $game): void
    {
        // Get current round number
        $currentRound = $game->getGameStateValue('round');
        $game->trace("Starting round $currentRound setup");

        // Step 1: Identify and eliminate players with health <= 0
        $playersToEliminate = self::identifyPlayersToEliminate($game);
        self::eliminatePlayers($game, $playersToEliminate);

        // Step 2: Check if the game should end
        $remainingPlayers = self::getRemainingPlayers($game);
        if (self::checkGameEndConditions($game, $remainingPlayers, $playersToEliminate)) {
            return; // Game has ended, no need to continue
        }

        // Step 3: Continue with normal round setup
        self::setupRoundFirstPlayer($game, $currentRound);

        // Step 4: Check market cards
        if (!self::checkAndUpdateMarket($game)) {
            return; // Not enough cards, game has ended
        }

        // Step 5: Reset player flags for the new round
        self::resetPlayerFlags($game);

        // Step 6: Fully eliminate players
        foreach ($playersToEliminate as $playerId => $playerData) {
            $game->eliminatePlayer($playerId);
            // Notify all players about the elimination
            $game->notifyAllPlayers('leaderEliminated', clienttranslate('${player_name} has been eliminated with ${health} health'), [
                'player_name' => $playerData['player_name'],
                'player_id' => $playerId,
                'leader_id' => $playerData['leader_id'],
                'health' => $playerData['health']
            ]);
        }

        // Move to the next state
        $game->gamestate->nextState('startRound');
    }

    /**
     * Identify players with health <= 0 who should be eliminated
     *
     * @param Game $game The game instance
     * @return array Array of players to eliminate with their data
     */
    private static function identifyPlayersToEliminate(Game $game): array
    {
        $game->trace("Checking for players with health <= 0");
        $playersToEliminate = [];
        $allResources = Resources::getAllResources($game);

        foreach ($allResources as $leaderId => $resources) {
            if ($resources['health'] <= 0) {
                $playerId = Players::getPlayerId($game, $leaderId);
                if (Players::isPlayerEliminated($game, $playerId)) {
                    $game->debug("Player $playerId with leader $leaderId is already eliminated");
                    continue;
                }
                $playerName = $game->getPlayerNameById($playerId);
                $is_first = Players::getFirstPlayerId($game) == $playerId;
                $playersToEliminate[$playerId] = [
                    'id' => $playerId,
                    'player_name' => $playerName,
                    'leader_id' => $leaderId,
                    'is_first' => $is_first,
                    'health' => $resources['health']
                ];
                $game->debug("Player $playerName (ID: $playerId) with leader $leaderId has health {$resources['health']} and will be eliminated");
            }
        }

        return $playersToEliminate;
    }

    /**
     * Eliminate players from the game
     *
     * @param Game $game The game instance
     * @param array $playersToEliminate Array of players to eliminate
     */
    private static function eliminatePlayers(Game $game, array $playersToEliminate): void
    {
        // First mark players as dead and notify
        foreach ($playersToEliminate as $playerId => $playerData) {
            // Mark player as dead in playerData
            $game->DbQuery("UPDATE playerData SET is_dead = 1 WHERE player_id = $playerId");

            $game->trace("Player {$playerData['player_name']} (ID: $playerId) has been eliminated");
        }
    }

    /**
     * Get the list of remaining players
     *
     * @param Game $game The game instance
     * @return array Array of remaining players
     */
    private static function getRemainingPlayers(Game $game): array
    {
        $remainingPlayers = $game->getCollectionFromDB(
            "SELECT p.player_id, p.player_name, pd.leader_id, r.health, pd.is_first
             FROM player p
             JOIN playerData pd ON p.player_id = pd.player_id
             JOIN resources r ON pd.leader_id = r.leader_id
             WHERE pd.is_dead = 0"
        );

        $game->debug("Remaining players: " . count($remainingPlayers));
        return $remainingPlayers;
    }

    /**
     * Check if the game should end based on various conditions
     *
     * @param Game $game The game instance
     * @param array $remainingPlayers Array of remaining players
     * @param array $playersToEliminate Array of players that were eliminated
     * @return bool True if the game has ended, false otherwise
     */
    private static function checkGameEndConditions(Game $game, array $remainingPlayers, array $playersToEliminate): bool
    {
        // Case 1: No players remaining, player with the highest health wins
        if (count($remainingPlayers) == 0) {
            $game->dump("Players to eliminate: ", $playersToEliminate);

            // Get the player with highest health among eliminated players
            $winner = self::getPlayerWithHighestHealth($game, $playersToEliminate);

            $game->trace("No players remaining, player with highest health wins: {$winner['name']} (ID: {$winner['id']}) with {$winner['health']} health");

            $message = $winner['is_tiebreaker'] && $winner['is_first']
                ? clienttranslate('${player_name} is the least wounded (${health}) and has the initial player token, so wins the game!')
                : clienttranslate('${player_name} is the least wounded (${health}) and wins the game!');

            $game->notifyAllPlayers('gameWinner', $message, [
                'player_name' => $winner['name'],
                'player_id' => $winner['id'],
                'leader_id' => $winner['leader_id'],
                'health' => $winner['health'],
                'is_tiebreaker' => $winner['is_tiebreaker']
            ]);
            $winnerId = $winner['id'];
            $game->DbQuery("UPDATE player SET player_score_aux = 1 WHERE player_id = $winnerId");
            $game->gamestate->nextState('gameOver');
            return true;
        }
        // Case 2: Only one player remains
        else if (count($remainingPlayers) == 1) {
            $winnerId = array_keys($remainingPlayers)[0];
            $winnerName = $remainingPlayers[$winnerId]['player_name'];
            $game->trace("Only one player remains: $winnerName (ID: $winnerId), they win");

            $game->notifyAllPlayers('gameWinner', clienttranslate('${player_name} is the last player standing and wins the game!'), [
                'player_name' => $winnerName,
                'player_id' => $winnerId,
                'leader_id' => $remainingPlayers[$winnerId]['leader_id']
            ]);

            $game->gamestate->nextState('gameOver');
            return true;
        }
        // Case 3: No more cards
        else if (!Market::hasEnoughCards($game)) {
            // Get the player with highest health among remaining players
            $winner = self::getPlayerWithHighestHealth($game, $remainingPlayers);

            $game->trace("No more cards available, player with highest health wins: {$winner['name']} (ID: {$winner['id']}) with {$winner['health']} health");

            $message = $winner['is_tiebreaker'] && $winner['is_first']
                ? clienttranslate('There are no more cards available. ${player_name} is the least wounded (${health}) and has the initial player token, so wins the game!')
                : clienttranslate('There are no more cards available. ${player_name} is the least wounded (${health}) and wins the game!');

            $game->notifyAllPlayers('gameWinner', $message, [
                'player_name' => $winner['name'],
                'player_id' => $winner['id'],
                'leader_id' => $winner['leader_id'],
                'health' => $winner['health'],
                'is_tiebreaker' => $winner['is_tiebreaker']
            ]);

            $winnerId = $winner['id'];
            $game->DbQuery("UPDATE player SET player_score_aux = 1 WHERE player_id = $winnerId");
            $game->gamestate->nextState('gameOver');
            return true;
        }

        // Game continues
        return false;
    }

    /**
     * Setup the first player for the round
     *
     * @param Game $game The game instance
     * @param int $currentRound The current round number
     */
    private static function setupRoundFirstPlayer(Game $game, int $currentRound): void
    {
        // If this is not the first round, rotate the first player
        if ($currentRound > 1) {
            $newFirstPlayerId = Players::rotateFirstPlayer($game);

            // Notify all players about the new first player
            $newFirstPlayerName = $game->getPlayerNameById($newFirstPlayerId);
            $game->notifyAllPlayers('firstPlayerSelected', clienttranslate('${player_name} is the first player for this round'), [
                'player_name' => $newFirstPlayerName,
                'player_id' => $newFirstPlayerId
            ]);
        }

        // Activate the first player for this round
        Players::activateFirstPlayer($game);
    }

    /**
     * Check if there are enough market cards and update the market
     *
     * @param Game $game The game instance
     * @return bool True if there are enough cards, false otherwise
     */
    private static function checkAndUpdateMarket(Game $game): bool
    {
        $hasEnoughCards = Market::hasEnoughCards($game);

        if (!$hasEnoughCards) {
            $game->notifyAllPlayers("notEnoughCards", clienttranslate("There are not enough cards in the market, ending the game"), []);
            $game->gamestate->nextState('gameOver');
            return false;
        }

        $marketCards = Market::getAllMarketCards($game);

        $game->notifyAllPlayers("marketUpdate", "", [
            "cards" => $marketCards,
            "cardsInDeck" => Market::getCardsInDeck($game)
        ]);

        return true;
    }

    /**
     * Reset player flags for the new round
     *
     * @param Game $game The game instance
     */
    private static function resetPlayerFlags(Game $game): void
    {
        // Reset attack and heal flags for the new round (only for living players)
        $game->DbQuery("UPDATE playerData SET has_attacked = 0, has_healed = 0 WHERE is_dead = 0");
    }

    /**
     * Get the player with the highest health from a list of players
     * Handles tie-breaking when multiple players have the same highest health
     *
     * @param Game $game The game instance
     * @param array $players Array of players to check
     * @return array Winner data with id, name, health, is_first, and is_tiebreaker
     */
    private static function getPlayerWithHighestHealth(Game $game, array $players): array
    {
        $highestHealth = -99;
        $winnerId = null;
        $winnerName = null;
        $winnerIsFirst = 0;
        $playersWithHighestHealth = [];

        // First pass: find the highest health value
        foreach ($players as $playerId => $player) {
            if ($player['health'] > $highestHealth) {
                $highestHealth = $player['health'];
            }
        }

        // Second pass: collect all players with the highest health
        foreach ($players as $playerId => $player) {
            if ($player['health'] == $highestHealth) {
                $playersWithHighestHealth[$playerId] = $player;
            }
        }

        $game->debug("players with highest health ($highestHealth): " . count($playersWithHighestHealth));

        // If multiple players have the same highest health
        if (count($playersWithHighestHealth) > 1) {
            foreach ($playersWithHighestHealth as $playerId => $player) {
                if ($player['is_first'] == 1) {
                    $winnerId = $playerId;
                    $winnerName = $player['player_name'];
                    $winnerIsFirst = 1;
                    break;
                }
            }

            // If no player with is_first found, use the first one in the list
            if ($winnerId === null) {
                $game->error("Multiple players with highest health but none has is_first flag");
                throw new BgaSystemException("Multiple players with highest health but none has is_first flag");
            }

            $game->trace("Multiple players have the highest health. $winnerName wins and has the initial player token");
        } else {
            // Only one player has the highest health
            $winnerId = key($playersWithHighestHealth);
            $winnerName = $playersWithHighestHealth[$winnerId]['player_name'];
        }

        return [
            'id' => $winnerId,
            'name' => $winnerName,
            'health' => $highestHealth,
            'is_first' => $winnerIsFirst,
            'is_tiebreaker' => count($playersWithHighestHealth) > 1
        ];
    }
}
